for (const mutation of [
  "death",
  "revive",
  "role",
  "camp",
  "state",
  "component",
  "instance",
  "source_ref",
  "source_field",
  "remaining",
  "expired",
])
  test(`late ${mutation} revokes only author without consumption`, async () => {
    const g = fixture();
    await run(g, async (r) => {
      if (r.actorId === 6) {
        const n = note(g, 1),
          rc = role(g, 1);
        switch (mutation) {
          case "death":
            g.world.getComponent(1, COMPONENT.Alive)!.alive = false;
            break;
          case "revive": {
            const alive = g.world.getComponent(1, COMPONENT.Alive)!;
            alive.alive = false;
            alive.alive = true;
            break;
          }
          case "role":
            rc.role = Role.Villager;
            break;
          case "camp":
            rc.camp = Camp.Good;
            break;
          case "state":
            (rc as { privateState: Readonly<Record<string, unknown>> }).privateState = {};
            break;
          case "component":
            g.world.addComponent(1, COMPONENT.WallNote, { ...n });
            break;
          case "instance":
            n.instanceId = "wrong";
            break;
          case "source_ref":
            n.source = { ...n.source };
            break;
          case "source_field":
            n.source.day = 2 as any;
            break;
          case "remaining":
            n.remaining = 0;
            break;
          case "expired":
            n.expired = true;
            break;
        }
      }
      return text(String(r.actorId));
    });
    expect((publicTexts(g) as any).texts).not.toContain("1");
    expect((publicTexts(g) as any).texts).toHaveLength(5);
    expect(
      g.events.some(
        (e) =>
          e.type === "wall_note_changed" &&
          e.payload.actorId === 1 &&
          e.payload.operation === "accepted",
      ),
    ).toBe(false);
  });

